CREATE TABLE public.attendance_events(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,employee_id bigint,event_type text,event_at timestamp,created_at timestamptz DEFAULT now());
ALTER TABLE public.event_corrections ADD COLUMN created_at timestamptz NOT NULL DEFAULT now();
CREATE TABLE public.store_settings(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,store_id bigint,open_minute int,close_minute int);
CREATE FUNCTION public.attendance_correction_effective_kst(timestamp,text,timestamptz) RETURNS timestamp LANGUAGE sql IMMUTABLE AS $$ SELECT $1 $$;
